import{c as a,Q as t,j as i,m as l}from"./chunks/framework.BPKcPtvA.js";const p=JSON.parse('{"title":"资产恢复指南 - 现货、永续合约、金库与 HYPE 质押资产","description":"详细解读机器人如何处理各类资产：将非 USDC 现货兑换、平仓合约、提取未锁定金库、以及分步解除 HYPE 质押并提取。","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://hyperliquidrecoverybot.github.io/zh/asset-recovery"}],["link",{"rel":"alternate","hreflang":"en","href":"https://hyperliquidrecoverybot.github.io/en/asset-recovery"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://hyperliquidrecoverybot.github.io/zh/asset-recovery"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://hyperliquidrecoverybot.github.io/en/asset-recovery"}],["meta",{"name":"keywords","content":"HYPE解除质押, 金库资产提取, 合约平仓找回, 现货兑换USDC, 质押收益找回"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:title","content":"资产恢复指南 - 现货、永续合约、金库与 HYPE 质押资产"}],["meta",{"property":"og:description","content":"详细解读机器人如何处理各类资产：将非 USDC 现货兑换、平仓合约、提取未锁定金库、以及分步解除 HYPE 质押并提取。"}],["meta",{"property":"og:url","content":"https://hyperliquidrecoverybot.github.io/zh/asset-recovery"}],["meta",{"name":"twitter:card","content":"summary"}],["meta",{"name":"twitter:title","content":"资产恢复指南 - 现货、永续合约、金库与 HYPE 质押资产"}],["meta",{"name":"twitter:description","content":"详细解读机器人如何处理各类资产：将非 USDC 现货兑换、平仓合约、提取未锁定金库、以及分步解除 HYPE 质押并提取。"}]]},"headers":[],"relativePath":"zh/asset-recovery.md","filePath":"zh/asset-recovery.md","lastUpdated":null}'),r={name:"zh/asset-recovery.md"};function o(n,e,h,s,c,d){return t(),i("div",null,[...e[0]||(e[0]=[l('<h1 id="hyperliquid-资金急救-风险地址受困资产提取执行流" tabindex="-1">Hyperliquid 资金急救：风险地址受困资产提取执行流 <a class="header-anchor" href="#hyperliquid-资金急救-风险地址受困资产提取执行流" aria-label="Permalink to &quot;Hyperliquid 资金急救：风险地址受困资产提取执行流&quot;">​</a></h1><p>本资产恢复核心流程专门针对被风控标记的 Hyperliquid 风险地址，提供将现货、合约及质押等各类受困资产安全转换为 USDC 并发起恢复提现到原 Arbitrum 钱包的自动化方案。</p><h2 id="执行前输入" tabindex="-1">执行前输入 <a class="header-anchor" href="#执行前输入" aria-label="Permalink to &quot;执行前输入&quot;">​</a></h2><p>您需要准备以下信息：</p><ol><li>源地址（待恢复地址）</li><li>私钥或助记词（仅用于签名）</li></ol><h2 id="标准-7-步流程" tabindex="-1">标准 7 步流程 <a class="header-anchor" href="#标准-7-步流程" aria-label="Permalink to &quot;标准 7 步流程&quot;">​</a></h2><p>机器人会根据实际资产自动生成并执行步骤；不满足条件的步骤会被跳过。</p><ol><li>检查账户状态</li><li>转换现货资产（非 USDC -&gt; USDC）</li><li>按需处理永续仓位</li><li>提取当前可提的金库资产</li><li>处理质押与可提余额</li><li>收取服务费</li><li>完成最终提现</li></ol><h2 id="步骤行为说明" tabindex="-1">步骤行为说明 <a class="header-anchor" href="#步骤行为说明" aria-label="Permalink to &quot;步骤行为说明&quot;">​</a></h2><h3 id="_1-账户准备、现货与永续" tabindex="-1">1) 账户准备、现货与永续 <a class="header-anchor" href="#_1-账户准备、现货与永续" aria-label="Permalink to &quot;1) 账户准备、现货与永续&quot;">​</a></h3><ul><li>账户状态：若恢复前需要先完成账户调整，机器人会优先处理。</li><li>现货：卖出非 USDC 资产，优先完成归集。</li><li>永续：按可执行条件关闭或处理相关仓位，为后续恢复做准备。</li></ul><h3 id="_2-金库" tabindex="-1">2) 金库 <a class="header-anchor" href="#_2-金库" aria-label="Permalink to &quot;2) 金库&quot;">​</a></h3><ul><li>当前可提资产：正常提取。</li><li>锁定资产或当前无可提额度资产：在预览与结果中标记为 waiting/locked，等待解锁或额度恢复后重试。</li></ul><h3 id="_3-质押-重点" tabindex="-1">3) 质押（重点） <a class="header-anchor" href="#_3-质押-重点" aria-label="Permalink to &quot;3) 质押（重点）&quot;">​</a></h3><p>机器人会区分三类状态：已解除质押可处理、仍在质押中、以及等待提现完成。</p><p>可能出现两种路径：</p><ul><li><strong>较快路径（2 次）</strong>：若部分质押余额已进入下一处理阶段，第一次运行可先提取其中一部分，剩余部分在等待期结束后继续处理。</li><li><strong>标准路径（3 次）</strong>：若余额仍处于完整质押状态，通常需要先解除质押，再在后续时间窗口完成提现。</li></ul><p>机器人会在结果中明确下一次建议执行时间。</p><h2 id="费用与到账" tabindex="-1">费用与到账 <a class="header-anchor" href="#费用与到账" aria-label="Permalink to &quot;费用与到账&quot;">​</a></h2><ul><li><code>Service Fee</code>：0.5%，最低 1 USDC</li><li><code>Withdrawal Fees</code>：2 USDC</li><li><code>Total Cost</code>：Service Fee + Withdrawal Fees</li><li><code>You Will Receive</code>：预估可恢复价值 - Total Cost</li></ul><p>详见 <a href="./fee-and-settlement">费用与到账</a>。</p><h2 id="执行结果阅读" tabindex="-1">执行结果阅读 <a class="header-anchor" href="#执行结果阅读" aria-label="Permalink to &quot;执行结果阅读&quot;">​</a></h2><p>您会看到每一步状态和最终摘要：</p><ul><li>Recovered Amount（恢复结果金额）</li><li>Actual Fees（实际费用）</li><li>交易哈希（可链上核验）</li></ul><p>说明：提现发起后到 Arbitrum 的到账是异步过程，受 Hyperliquid 处理速度影响，通常可能需要几分钟到十几分钟。</p><p>状态定义见 <a href="./execution-status">执行状态说明</a>。</p><p>如果结果页提示仍需等待，请按建议时间再次运行。</p><h2 id="失败与重试策略" tabindex="-1">失败与重试策略 <a class="header-anchor" href="#失败与重试策略" aria-label="Permalink to &quot;失败与重试策略&quot;">​</a></h2><ul><li>网络短时异常：可直接重试。</li><li>锁定/等待状态：按提示时间再次运行。</li><li>输入错误（地址或私钥不匹配）：修正后重试。</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><ol><li>先执行一次地址检测，确认资产结构。</li><li>无需填写目标地址，资产将默认提现到源地址对应的 Arbitrum 地址。</li><li>对包含质押或金库资产的地址，设置提醒并按时间窗口重跑。</li></ol>',31)])])}const m=a(r,[["render",o]]);export{p as __pageData,m as default};
